      de: ["Jetzt als Davao de Oro bekannt", "Wichtiger Produzent von Bananen und Reis", "Das Gelände ist eine Mischung aus Tälern, Bergen und Küstenebenen"],
      hu: ["Ma Davao de Oro néven ismert", "Jelentős banán- és rizstermelő", "A terület völgyek, hegyek és tengerparti síkságok keveréke"],
      ro: ["Acum cunoscut sub numele de Davao de Oro", "Producător major de banane și orez", "Terenul este un amestec de văi, munți și câmpii de coastă"],
      en: ["Now known as Davao de Oro", "Major producer of bananas and rice", "The terrain is a mix of valleys, mountains, and coastal plains"],
      es: ["Ahora conocida como Davao de Oro", "Importante productor de plátanos y arroz", "El terreno es una mezcla de valles, montañas y llanuras costeras"],
      pt: ["Agora conhecida como Davao de Oro", "Importante produtor de bananas e arroz", "O terreno é uma mistura de vales, montanhas e planícies costeiras"],
      fr: ["Désormais connue sous le nom de Davao de Oro", "Producteur important de bananes et de riz", "Le terrain est un mélange de vallées, de montagnes et de plaines côtières"],
