      hu: "A Fülöp-szigetek harmadik leghosszabb folyójának völgye, amely Kelet-Mindanaón húzódik keresztül.",
      ro: "Valea celui de-al treilea cel mai lung râu din Filipine, care se întinde prin estul Mindanao.",
      en: "The valley of the third longest river in the Philippines, stretching through eastern Mindanao.",
      es: "El valle del tercer río más largo de las Filipinas, que se extiende por el este de Mindanao.",
      pt: "O vale do terceiro rio mais longo das Filipinas, que se estende pelo leste de Mindanao.",
      fr: "La vallée de la troisième plus longue rivière des Philippines, s'étendant à travers l'est de Mindanao.",
