      ro: ["Include Sanctuarul Faunei Sălbatice Agusan Marsh", "Regiune importantă pentru exploatare forestieră și agricultură", "Predispusă la inundații în timpul sezonului ploios"],
      en: ["Includes the Agusan Marsh Wildlife Sanctuary", "Important region for logging and agriculture", "Prone to flooding during the rainy season"],
      es: ["Incluye el Santuario de Vida Silvestre de los Pantanos de Agusan", "Región importante para la industria maderera y la agricultura", "Propenso a inundaciones durante la temporada de lluvias"],
      pt: ["Inclui o Santuário de Vida Selvagem dos Pântanos de Agusan", "Região importante para a indústria madeireira e agricultura", "Propenso a inundações durante a estação chuvosa"],
